          if (typeof row.id === 'string') existingSourceIds.add(row.id);
        }
      }
    }

    return rows.map((row) => {
      const missing = Boolean(row.source_character_id) && !existingSourceIds.has(row.source_character_id as string);
      return mapToViewModel(row, missing);
    });
  }

