      throw new Error(`Neue Look-Version fehlgeschlagen: ${versionError.message}`);
    }

    const { error: bumpError } = await raceWithTimeoutReject(
      supabase
        .from(PROFILES)
        .update({ current_version: nextVersion })
        .eq('id', profileId)
