async deleteSession(sessionId: string): Promise<void> {
    await this.requireAuthUser();
    const id = sessionId.trim();
    if (!id) {
      throw new Error('Session-ID fehlt');
    }

    const { error } = await supabase.from(this.tableName).delete().eq('id', id);

